// T1 host test for ChareffDecode.h (the pure decoder + pixel-width text layer of CharEffectsPanel.cpp; doc 20 Phase 5 #4).
// Build/run: python3 scripts/run_tests.py -k chareff   (args from test.toml: <cases file> <live DECODE samples>)
//
// Checks the C++ the DLL runs against scripts/check_effect_decode.py (the Python oracle):
//   1. testdata/decode_cases.txt, generated by `check_effect_decode.py --emit-cases` (format in that script's header):
//      every decode / wrap / px / fit / marq case must match exactly;
//   2. research/decode_samples_live.txt: the real DECODE lines the DLL logged in play must decode to the same strings
//      (KnownChanges = intentional output changes since an older build logged the line, as in the Python script).
// Fails (nonzero) if either file is missing/unreadable, a line cannot be parsed, or a section has zero cases.
#include "ChareffDecode.h"
#include "check.h"
#include <cstdlib>
#include <string>
#include <vector>

using namespace cfx;

static std::string unesc(const std::string& s) {
    std::string o;
    for (size_t i = 0; i < s.size(); ++i) {
        if (s[i] == '\\' && i + 1 < s.size()) {
            char c = s[++i];
            o += c == 't' ? '\t' : c == 'n' ? '\n' : c;
        } else o += s[i];
    }
    return o;
}
static std::vector<std::string> split(const std::string& s, char sep) {   // keeps empty fields, incl. a trailing one
    std::vector<std::string> v; size_t a = 0;
    for (;;) {
        size_t b = s.find(sep, a);
        if (b == std::string::npos) { v.push_back(s.substr(a)); return v; }
        v.push_back(s.substr(a, b - a)); a = b + 1;
    }
}
static bool readLines(const char* path, std::vector<std::string>* out) {
    FILE* f = fopen(path, "rb");
    if (!f) return false;
    std::string cur; int c;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') { if (!cur.empty() && cur.back() == '\r') cur.pop_back(); out->push_back(cur); cur.clear(); }
        else cur += (char)c;
    }
    if (!cur.empty()) out->push_back(cur);
    fclose(f);
    return true;
}
static Font fontOf(const std::string& s) { return s == "F10" ? F10 : F16; }
static float num(const std::string& s) { return strtof(s.c_str(), nullptr); }

// the DLL's collect path: atomOf + addAtom per effect, then formatStats into an Entry
static Entry decodeEntry(const std::vector<std::pair<int, std::vector<int>>>& effs) {
    AtomSet set = {};
    for (auto& e : effs) {
        int v[8] = {}; int n = (int)e.second.size(); if (n > 8) n = 8;
        for (int i = 0; i < n; ++i) v[i] = e.second[i];
        Atom a;
        if (atomOf(e.first, v, n, &a)) addAtom(set, a);
    }
    Entry en = {};
    formatStats(en, set);
    return en;
}

static int g_cases[6];   // decode wrap px fit marq total
static int g_bad;        // lines that could not be parsed

static void runCase(const std::vector<std::string>& f, const TextCtx& ctx, int lineNo) {
    char what[160];
    const std::string& kind = f[0];
    if (kind == "decode" && f.size() >= 4) {
        ++g_cases[0];
        snprintf(what, sizeof what, "decode L%d %.100s", lineNo, unesc(f[1]).c_str());
        std::vector<std::pair<int, std::vector<int>>> effs;
        if (f[2] != "-")
            for (auto& item : split(f[2], ';')) {
                size_t c = item.find(':');
                std::pair<int, std::vector<int>> e;
                e.first = (int)strtol(item.substr(0, c).c_str(), nullptr, 16);
                std::string ints = c == std::string::npos ? "" : item.substr(c + 1);
                if (!ints.empty()) for (auto& t : split(ints, ',')) e.second.push_back(atoi(t.c_str()));
                effs.push_back(e);
            }
        Entry en = decodeEntry(effs);
        bool ok = kt::CheckEq(what, en.stat, unesc(f[3]).c_str());
        ok &= kt::CheckEq(what, en.nLines, (int)f.size() - 4);
        for (int i = 0; i < en.nLines && i + 4 < (int)f.size(); ++i) ok &= kt::CheckEq(what, en.lines[i], unesc(f[4 + i]).c_str());
        (void)ok;
    } else if (kind == "wrap" && f.size() >= 9 && f.size() % 2 == 1) {
        ++g_cases[1];
        snprintf(what, sizeof what, "wrap L%d %.100s", lineNo, unesc(f[1]).c_str());
        int cap = atoi(f[3].c_str());
        std::vector<char> buf((size_t)cap + 1, 'X'); int len = 0;
        std::string lines; bool px = f[2] == "px10";
        for (size_t i = 7; i + 1 < f.size(); i += 2) {
            float mx = num(f[i]); std::string src = unesc(f[i + 1]);
            int n = px ? cfx::wrapAppend(ctx, src.c_str(), mx, buf.data(), &len, cap)
                       : wrapAppendW([](const char*, int n2) { return (float)n2; }, src.c_str(), mx, buf.data(), &len, cap);
            lines += (lines.empty() ? "" : ",") + std::to_string(n);
        }
        // an empty buffer is only valid when nothing was ever emitted (C reads the string up to the NUL)
        if (len == 0) buf[0] = 0;
        kt::CheckEq(what, lines.c_str(), f[4].c_str());
        kt::CheckEq(what, buf.data(), unesc(f[5]).c_str());
        kt::CheckEq(what, len, atoi(f[6].c_str()));
    } else if (kind == "px" && f.size() == 5) {
        ++g_cases[2];
        snprintf(what, sizeof what, "px L%d %.100s", lineNo, unesc(f[1]).c_str());
        std::string t = unesc(f[3]);
        float got = textPx(ctx, t.c_str(), (int)t.size(), fontOf(f[2])), want = num(f[4]);
        char d[80]; snprintf(d, sizeof d, "got %.9g want %.9g", got, want);
        kt::Check(what, got == want, d);
    } else if (kind == "fit" && f.size() == 7) {
        ++g_cases[3];
        snprintf(what, sizeof what, "fit L%d %.100s", lineNo, unesc(f[1]).c_str());
        char out[256]; std::string t = unesc(f[4]);
        bool cut = fitText(ctx, t.c_str(), num(f[3]), out, sizeof out, fontOf(f[2]));
        kt::CheckEq(what, out, unesc(f[5]).c_str());
        kt::CheckEq(what, cut, f[6] == "1");
    } else if (kind == "marq" && f.size() == 8) {
        ++g_cases[4];
        snprintf(what, sizeof what, "marq L%d %.100s", lineNo, unesc(f[1]).c_str());
        char out[256]; int mo = -1; std::string t = unesc(f[5]);
        marqueeText(ctx, t.c_str(), num(f[3]), atoi(f[4].c_str()), out, sizeof out, &mo, fontOf(f[2]));
        kt::CheckEq(what, out, unesc(f[6]).c_str());
        kt::CheckEq(what, mo, atoi(f[7].c_str()));
    } else {
        ++g_bad;
        snprintf(what, sizeof what, "cases L%d: unparsable '%.40s' (%d fields)", lineNo, kind.c_str(), (int)f.size());
        kt::Check(what, false);
    }
}

// ---- live DECODE samples: "HH:MM:SS.mmm DECODE: type=0x1c ints=[199,0,...] -> 'Speed +199%' / 'Movement ...'" ----
struct Known { int type; int ints[8]; const char* sh; const char* lg; };
static const Known kKnownChanges[] = {   // build 4b -> 4c, as KNOWN_CHANGES in scripts/check_effect_decode.py
    {0x1c, {199, 0, 0, 0, 0, 0, 0, 0}, "Speed +99%", "Movement speed +99% (engine cap +50%)"},
};
static int g_samples;
static void runSample(const std::string& line, int lineNo) {
    size_t p = line.find("DECODE: type=0x");
    if (p == std::string::npos) return;
    ++g_samples;
    char what[160]; snprintf(what, sizeof what, "live L%d", lineNo);
    char* e = nullptr;
    int type = (int)strtol(line.c_str() + p + 15, &e, 16);
    const char* q = strstr(e, "ints=[");
    const char* arrow = strstr(e, "] -> ");
    if (!q || !arrow) { ++g_bad; kt::Check(what, false, "unparsable live line"); return; }
    int v[8] = {}, n = 0;
    for (const char* c = q + 6; c < arrow && n < 8;) { v[n++] = (int)strtol(c, (char**)&c, 10); if (*c == ',') ++c; }
    const char* rest = arrow + 5;
    Atom a; bool has = atomOf(type, v, n, &a);
    if (!strncmp(rest, "(no stat shown)", 15)) { kt::Check(what, !has, "log says no stat, decoder produced an atom"); return; }
    // '<sh>' / '<lg>'
    if (*rest != '\'') { ++g_bad; kt::Check(what, false, "unparsable stat part"); return; }
    const char* m = strstr(rest, "' / '");
    if (!m) { ++g_bad; kt::Check(what, false, "unparsable stat part"); return; }
    std::string wsh(rest + 1, m), wlg(m + 5);
    if (!wlg.empty() && wlg.back() == '\'') wlg.pop_back();
    for (auto& k : kKnownChanges) {
        bool same = k.type == type; for (int i = 0; i < 8; ++i) same &= k.ints[i] == v[i];
        if (same) { wsh = k.sh; wlg = k.lg; }
    }
    if (!kt::Check(what, has, "log has a stat, decoder produced no atom")) return;
    char sh[48], lg[LineLen]; fmtAtom(a, sh, sizeof sh, lg, sizeof lg);
    kt::CheckEq(what, sh, wsh.c_str());
    kt::CheckEq(what, lg, wlg.c_str());
}

int main(int argc, char** argv) {
    if (argc < 3) { std::printf("FAIL usage: chareff_decode_test <decode_cases.txt> <decode_samples_live.txt>\n"); return 2; }
    std::vector<std::string> lines;
    if (!readLines(argv[1], &lines)) { std::printf("FAIL cannot read cases file %s\n", argv[1]); return 1; }
    TextCtx ctx = {0, 0, 0}; bool haveCtx = false;
    for (size_t i = 0; i < lines.size(); ++i) {
        if (lines[i].empty() || lines[i][0] == '#') continue;
        auto f = split(lines[i], '\t');
        if (f[0] == "ctx" && f.size() == 4) { ctx = {num(f[1]), num(f[2]), num(f[3])}; haveCtx = true; continue; }
        if (!haveCtx) { std::printf("FAIL %s: case before the ctx line (L%d)\n", argv[1], (int)i + 1); return 1; }
        runCase(f, ctx, (int)i + 1);
    }
    static const char* const names[5] = {"decode", "wrap", "px", "fit", "marq"};
    int total = 0;
    for (int k = 0; k < 5; ++k) { total += g_cases[k]; kt::Check(names[k], g_cases[k] > 0, "zero cases of this kind parsed"); }
    kt::Check("cases file parsed at least one case", total > 0);
    kt::Check("no unparsable case lines", g_bad == 0);

    std::vector<std::string> live;
    if (!readLines(argv[2], &live)) { std::printf("FAIL cannot read live samples %s\n", argv[2]); return 1; }
    for (size_t i = 0; i < live.size(); ++i) runSample(live[i], (int)i + 1);
    kt::Check("live samples: at least one DECODE line replayed", g_samples > 0);

    // F29: A_REGEN period b = INT_MAX must not overflow (x.b + 500) -- 2147483647 ms -> 2147484 s
    {
        int v[2] = {1, 2147483647}; Atom a; bool has = atomOf(0x07, v, 2, &a);
        kt::Check("F29 regen INT_MAX has an atom", has);
        char sh[48], lg[LineLen]; sh[0] = lg[0] = 0;
        if (has) fmtAtom(a, sh, sizeof sh, lg, sizeof lg);
        kt::CheckEq("F29 regen INT_MAX short", sh, "Regen 1/2147484s");
        kt::CheckEq("F29 regen INT_MAX long", lg, "Regenerates 1 Vitality every 2147484 s");
    }
    // F30: marqueeText with a negative offset behaves as offset 0 (no read before the buffer)
    {
        const char* txt = "Immune: Piercing, Slashing, Universal, Acid, Cold";
        char o0[256], oN[256]; int m0 = -1, mN = -1;
        marqueeText(ctx, txt, 120.0f, 0, o0, sizeof o0, &m0);
        marqueeText(ctx, txt, 120.0f, -5, oN, sizeof oN, &mN);
        kt::CheckEq("F30 marquee off=-5 text equals off=0", oN, o0);
        kt::CheckEq("F30 marquee off=-5 maxOff equals off=0", mN, m0);
    }

    std::printf("chareff_decode_test: %d cases (decode %d, wrap %d, px %d, fit %d, marq %d), %d live samples\n", total,
                g_cases[0], g_cases[1], g_cases[2], g_cases[3], g_cases[4], g_samples);
    return kt::Report("chareff_decode_test");
}
